import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import '../state/app_state.dart';
class CartPage extends StatelessWidget { const CartPage({super.key, required this.onBrowse}); final VoidCallback onBrowse;
 @override Widget build(BuildContext context) { final s = context.watch<AppState>(); if (s.cart.isEmpty) return Center(child: Column(mainAxisSize: MainAxisSize.min, children: [const Icon(Icons.shopping_cart_outlined, size: 56), const SizedBox(height: 12), const Text('Your cart is empty'), const SizedBox(height: 12), FilledButton(onPressed: onBrowse, child: const Text('Browse products'))])); return Column(children: [Expanded(child: ListView.separated(padding: const EdgeInsets.all(16), itemCount: s.cart.length, separatorBuilder: (_,__) => const Divider(), itemBuilder: (_, i) { final item=s.cart[i]; return ListTile(contentPadding: EdgeInsets.zero, leading: SizedBox(width: 56, child: Image.network(item.product.image, fit: BoxFit.contain)), title: Text(item.product.title, maxLines: 2, overflow: TextOverflow.ellipsis), subtitle: Text('\$${item.product.price.toStringAsFixed(2)}'), trailing: Row(mainAxisSize: MainAxisSize.min, children: [IconButton(onPressed: () => s.setQuantity(item.product, item.quantity - 1), icon: const Icon(Icons.remove_circle_outline)), Text('${item.quantity}'), IconButton(onPressed: () => s.setQuantity(item.product, item.quantity + 1), icon: const Icon(Icons.add_circle_outline))])); })), SafeArea(top: false, child: Container(padding: const EdgeInsets.all(20), decoration: BoxDecoration(color: Theme.of(context).colorScheme.surfaceContainerHighest), child: Row(children: [Text('Total', style: Theme.of(context).textTheme.titleLarge), const Spacer(), Text('\$${s.total.toStringAsFixed(2)}', style: Theme.of(context).textTheme.titleLarge), const SizedBox(width: 12), FilledButton(onPressed: () => ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Checkout is not available in the demo API.'))), child: const Text('Checkout'))]))) ]); }
}
